/**
 * Registro de Glifos do Design System WhatsApp Mobile.
 *
 * IMPORTANTE: todo o dado vetorial abaixo foi copiado literalmente dos exports
 * SVG do arquivo Figma "WhatsApp Clone - Dark mode (Community) - cópia"
 * (fileKey `MSEV2CgXr84WwOyMauIBy2`). Nenhum caminho foi desenhado à mão,
 * aproximado ou substituído por outra biblioteca de ícones. O `viewBox`
 * original é preservado — não normalizado para 24×24 — de modo que as
 * proporções sejam idênticas às do arquivo de design.
 *
 * Para adicionar um glifo novo: exporte o SVG do Figma, copie os atributos
 * (`d`, `cx/cy/r`, `x1/y1/x2/y2`) sem edição e registre `figmaName`, `viewBox`
 * e `usage`.
 */

/**
 * Formas vetoriais suportadas por um glifo.
 */
export type WaIconShape =
  | {
      type: 'path';
      /** Atributo `d` literal do export do Figma */
      d: string;
      /** Aplica `fill-rule="evenodd"` quando verdadeiro */
      evenOdd?: boolean;
      /** Cor fixa; quando ausente, herda `currentColor` */
      fill?: string;
      /** Remove o preenchimento (caminho apenas com traço) */
      noFill?: boolean;
      stroke?: string;
      strokeWidth?: number;
      strokeLinecap?: 'butt' | 'round' | 'square';
      strokeMiterlimit?: number;
      /**
       * Deslocamento aplicado via `transform="translate(x, y)"` quando o glifo
       * combina dois nós do Figma posicionados em coordenadas diferentes.
       * Preserva o atributo `d` literal — nunca reescreva as coordenadas.
       */
      translate?: [number, number];
    }
  | {
      type: 'circle';
      cx: number;
      cy: number;
      r: number;
      fill?: string;
      noFill?: boolean;
      stroke?: string;
      strokeWidth?: number;
    }
  | {
      type: 'line';
      x1: number;
      y1: number;
      x2: number;
      y2: number;
      stroke?: string;
      strokeWidth?: number;
      strokeLinecap?: 'butt' | 'round' | 'square';
    };

/**
 * Definição completa de um glifo do WhatsApp Mobile.
 */
export interface WaIconDefinition {
  /** Nome da camada correspondente no Figma */
  figmaName: string;
  /** viewBox original preservando a proporção exata do export */
  viewBox: string;
  /** Formas vetoriais que compõem o glifo */
  shapes: WaIconShape[];
  /** Contexto de uso do glifo dentro do produto */
  usage: string;
  /** Node do Figma em que o glifo foi lido */
  figmaNode?: string;
}

/**
 * Nomes de todos os glifos disponíveis na biblioteca.
 */
